// measure_number crag.func — derive measure number from a beat event
// (named-pin form).
//
// Takes the beat event produced by `metronome` plus a `beat_count` and
// `beats_per_measure` value, and republishes a beat event annotated with the
// 0-based measure number.
//
// Named control pins (Phase 5 migration from the legacy
// `^bb0(i1, i32, i32, i32) -> (i1, i32, i32)` positional form — operand and
// result types are unchanged, so call sites are identical):
//
//   Inputs:
//     beat               — (event_void) beat trigger from metronome: (fired, at)
//     beat_count         — (param_int, i32) total beats elapsed (0-indexed)
//     beats_per_measure  — (param_int, i32) beats per measure (e.g. 4 for 4/4)
//
//   Output (event_output_int, subtype "measure_number"):
//     measure            — (fired, sample_offset, measure)
//       fired         — pass-through of the input fired flag
//       sample_offset — pass-through of the input beat offset
//       measure       — 0-based measure number = beat_count / beats_per_measure
//
// Typical usage inside a graph (call site unchanged from the legacy form):
//   %f, %at = crag.func_ref "metronome"(%ref, %period) : (i32, i32) -> (i1, i32)
//   %f2, %at2, %measure = crag.func_ref "measure_number"(%f, %at, %count, %bpm)
//       : (i1, i32, i32, i32) -> (i1, i32, i32)

module {
  crag.func name = "measure_number" {
    %fired, %at        = crag.event_void "beat" subtype = "beat" : i1, i32
    %beat_count        = crag.param_int "beat_count"
                             min = 0 max = 1000000 default = 0 : i32
    %beats_per_measure = crag.param_int "beats_per_measure"
                             min = 1 max = 32 default = 4 : i32

    // measure = beat_count / beats_per_measure (integer floor division)
    %measure = arith.divsi %beat_count, %beats_per_measure : i32

    crag.event_output_int "measure" %fired, %at, %measure
        subtype = "measure_number" : i1, i32, i32
    crag.func_return
  }
}

sequencing/metronome.crag.mlir:
// Metronome crag.func — sample-accurate beat detection (named-pin form).
//
// Given a reference beat position (`beat_ref_sample`) and a period
// (`beat_period_samples`), publishes a `beat` event that fires within the
// current audio block at the sample offset of the beat.
//
// Named control pins (the legacy `^bb0(i64, i64) -> (i1, i32)`
// positional form was replaced by public named pins so the metronome is a
// discoverable, wireable control node):
//
//   Inputs (param_int, i32):
//     beat_ref_sample      — absolute sample index of beat 0
//     beat_period_samples  — number of samples between consecutive beats
//
//   Output (event_output_void, subtype "beat"):
//     beat                 — (fired, sample_offset)
//       fired         — true when a beat falls in [curframe, curframe + block_size)
//       sample_offset — 0-based offset of the beat within the current block
//                       (0 when not fired)
//
// Integer width: control params are i32 (the dialect has no i64 param
// yet). Sample indices are sign-extended to
// i64 internally so the modular arithmetic matches the original i64 logic
// bit-for-bit across the full i32 input range (≈12.4 h at 48 kHz).
//
// The function uses `crag.curframe` and `crag.block_size`, both resolved at
// lowering time and therefore valid inside any inlined context.  This func is
// eliminated by `crag-inline-funcs` before lowering.

module {
  crag.func name = "metronome" {
    // --- Named control inputs (i32, sign-extended to i64 below) ----------
    %beat_ref_sample_i32 = crag.param_int "beat_ref_sample"
                               min = 0 max = 2147483647 default = 0 : i32
    %beat_period_samples_i32 = crag.param_int "beat_period_samples"
                               min = 1 max = 2147483647 default = 24000 : i32

    %beat_ref_sample     = arith.extsi %beat_ref_sample_i32     : i32 to i64
    %beat_period_samples = arith.extsi %beat_period_samples_i32 : i32 to i64

    %cur_frame   = crag.curframe  : i64
    %block_size  = crag.block_size : i64
    %zero_i64    = arith.constant 0 : i64
    %zero_i32    = arith.constant 0 : i32
    %true_val    = arith.constant 1 : i1

    // elapsed = cur_frame - beat_ref_sample (signed)
    %elapsed     = arith.subi %cur_frame, %beat_ref_sample : i64

    // before_start = elapsed < 0 (no beats have occurred yet)
    %before_start = arith.cmpi slt, %elapsed, %zero_i64 : i64

    // safe_elapsed = max(0, elapsed) — avoid negative remainder
    %safe_elapsed = arith.select %before_start, %zero_i64, %elapsed : i64

    // elapsed_mod = safe_elapsed % beat_period_samples
    // This is in [0, beat_period_samples - 1] because safe_elapsed >= 0.
    %elapsed_mod  = arith.remsi %safe_elapsed, %beat_period_samples : i64

    // offset_to_beat within this block:
    //   elapsed_mod == 0 => beat falls exactly at cur_frame (offset = 0)
    //   elapsed_mod != 0 => next beat is (period - elapsed_mod) samples ahead
    %mod_is_zero  = arith.cmpi eq, %elapsed_mod, %zero_i64 : i64
    %raw_offset   = arith.subi %beat_period_samples, %elapsed_mod : i64
    %offset_to_beat = arith.select %mod_is_zero, %zero_i64, %raw_offset : i64

    // fired = !before_start && offset_to_beat < block_size
    %in_block     = arith.cmpi slt, %offset_to_beat, %block_size : i64
    %not_before   = arith.xori %before_start, %true_val : i1
    %fired        = arith.andi %not_before, %in_block : i1

    // sample_offset as i32, clamped to 0 when not fired
    %offset_sel   = arith.select %fired, %offset_to_beat, %zero_i64 : i64
    %sample_offset = arith.trunci %offset_sel : i64 to i32

    // --- Named control output --------------------------------------------
    crag.event_output_void "beat" %fired, %sample_offset
        subtype = "beat" : i1, i32
    crag.func_return
  }
}
